import{_ as e,C as i,c as n,o as r,j as l,G as t,b as a,a0 as s,a as u,w as o,a1 as h}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Trainingsübungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/training/drills.md","filePath":"de/education/training/drills.md"}');const d=e({name:"de/education/training/drills.md"},[["render",function(e,g,d,c,p,b){const f=i("AdBanner"),m=i("Mermaid"),k=i("AdInArticle");return r(),n("div",null,[g[1]||(g[1]=l("h1",{id:"trainingsubungen",tabindex:"-1"},[u("Trainingsübungen "),l("a",{class:"header-anchor",href:"#trainingsubungen","aria-label":'Permalink to "Trainingsübungen"'},"​")],-1)),t(f),g[2]||(g[2]=l("p",null,"Hier findest du bewährte Übungen, die von Spitzenspielern eingesetzt werden. Jede Übung hat einen bestimmten Zweck – wähle diejenige aus, die du entwickeln möchtest.",-1)),g[3]||(g[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"Die große Idee"),l("p",null,[l("strong",null,"Jede Übung hat einen bestimmten Zweck."),u(" Werfen Sie die Boulekugeln nicht einfach wahllos – wählen Sie Übungen, die Ihre Schwächen gezielt angehen und Sie bei der Erreichung Ihrer Ziele unterstützen. Verfolgen Sie Ihre Fortschritte, um Verbesserungen festzustellen.")])],-1)),(r(),a(h,null,{default:o(()=>[t(m,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BTrainings%C3%BCbungen%5D%20--%3E%20B%5BZeige%C3%BCbungen%5D%0A%20%20%20%20A%20--%3E%20C%5BSchie%C3%9F%C3%BCbungen%5D%0A%20%20%20%20A%20--%3E%20D%5BMentale%20%C3%9Cbungen%5D%0A%20%20%20%20A%20--%3E%20E%5BSpielsimulation%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BGenauigkeit%5D%0A%20%20%20%20B%20--%3E%20G%5BDistanzkontrolle%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BTrefferquote%5D%0A%20%20%20%20C%20--%3E%20I%5BDruckschie%C3%9Fen%5D%0A%0A%20%20%20%20D%20--%3E%20J%5BRoutinepraxis%5D%0A%20%20%20%20D%20--%3E%20K%5BVisualisierung%5D%0A%0A%20%20%20%20E%20--%3E%20L%5BWettkampfbereitschaft%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[u(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=s('<h2 id="zeigeubungen" tabindex="-1">Zeigeübungen <a class="header-anchor" href="#zeigeubungen" aria-label="Permalink to &quot;Zeigeübungen&quot;">​</a></h2><h3 id="die-gasse" tabindex="-1">Die Gasse <a class="header-anchor" href="#die-gasse" aria-label="Permalink to &quot;Die Gasse&quot;">​</a></h3><p><strong>Zweck:</strong> Isolierung des Abwurfwinkels und der Linienkonsistenz.</p><p><strong>Aufstellen:</strong></p><ul><li>Platzieren Sie zwei Markierungen im Abstand von 30-40 cm, etwa 1 Meter vom Kreis entfernt.</li><li>Das Ziel ist 7-9 Meter entfernt.</li></ul><p><strong>Bohren:</strong></p><ul><li>Wirf durch die &quot;Gasse&quot; (zwischen den Markierungen)</li><li>Jeder Wurf, der eine Markierung trifft, ist &quot;tot&quot;.</li><li>Fokus auf einen einheitlichen Freigabepunkt</li></ul><p><strong>Progression:</strong></p><ul><li>Verenge die Gasse, während du dich verbesserst</li><li>Variieren Sie die Zielentfernung</li><li>Füge eine spezifische Landezone hinzu</li></ul><h3 id="prazisionszonen" tabindex="-1">Präzisionszonen <a class="header-anchor" href="#prazisionszonen" aria-label="Permalink to &quot;Präzisionszonen&quot;">​</a></h3><p><strong>Zweck:</strong> Entwicklung von Genauigkeit in bestimmten Bereichen</p><p><strong>Aufstellen:</strong></p><ul><li>Markieren Sie Zonen um ein Ziel herum (z. B. Kreise bei 20 cm, 40 cm, 60 cm).</li><li>Oder man nutzt natürliche Markierungen im Gelände.</li></ul><p><strong>Wertung:</strong></p><ul><li>Innerhalb von 20 cm: 3 Punkte</li><li>Innerhalb von 40 cm: 2 Punkte</li><li>Innerhalb von 60 cm: 1 Punkt</li><li>Außerhalb: 0 Punkte</li></ul><p><strong>Bohren:</strong></p><ul><li>Wirf 10 Boules und notiere deine Punktzahl.</li><li>Ziel: Kontinuierliche Verbesserung über die Trainingseinheiten hinweg</li></ul><h3 id="distanzvariation" tabindex="-1">Distanzvariation <a class="header-anchor" href="#distanzvariation" aria-label="Permalink to &quot;Distanzvariation&quot;">​</a></h3><p><strong>Zweck:</strong> Entwicklung der Tiefenkontrolle</p><p><strong>Aufstellen:</strong></p><ul><li>Platzieren Sie Ziele in 6 m, 7 m, 8 m, 9 m und 10 m Entfernung.</li></ul><p><strong>Bohren:</strong></p><ul><li>Werfen Sie in zufälliger Reihenfolge auf jede Entfernung.</li><li>Der Partner ruft die Entfernung an</li><li>Konzentriere dich auf die Gewichtsanpassung, nicht auf die Technik.</li></ul><p><strong>Variation:</strong></p><ul><li>Fügen Sie nach der Freigabe die Aufrufe „short“ und „long“ hinzu.</li><li>Muss während des Fluges korrigiert werden (entwickelt ein Gefühl dafür).</li></ul><h2 id="schießubungen" tabindex="-1">Schießübungen <a class="header-anchor" href="#schießubungen" aria-label="Permalink to &quot;Schießübungen&quot;">​</a></h2><h3 id="die-schießleiter" tabindex="-1">Die Schießleiter <a class="header-anchor" href="#die-schießleiter" aria-label="Permalink to &quot;Die Schießleiter&quot;">​</a></h3><p><strong>Zweck:</strong> Erhöhung der Genauigkeit unter progressivem Druck</p><p><strong>Aufstellen:</strong></p><ul><li>Platziere eine Zielkugel in 6 Metern Entfernung.</li><li>Markieren Sie Abstände bei 7 m, 8 m, 9 m, 10 m</li></ul><p><strong>Bohren:</strong></p><ul><li>Beginnen Sie bei 6 Metern.</li><li>Treffer = einen Meter zurückweichen</li><li>Fehlschlag = einen Meter vorwärts (oder neu starten)</li><li>Ziel: 10 Meter erreichen</li></ul><p><strong>Varianten:</strong></p><ul><li>Strenge Version: Jeder Fehlwurf führt zurück zu 6 m.</li><li>Zeitversion: Wie weit kommst du in 10 Minuten?</li><li>Teamversion: Wechseln Sie sich mit dem Partner ab.</li></ul>',34)),t(k),g[5]||(g[5]=s('<h3 id="the-barrier-blox" tabindex="-1">The Barrier (Blox) <a class="header-anchor" href="#the-barrier-blox" aria-label="Permalink to &quot;The Barrier (Blox)&quot;">​</a></h3><p><strong>Zweck:</strong> Erzwingen von Schüssen mit hohem Bogen</p><p><strong>Aufstellen:</strong></p><ul><li>Platzieren Sie eine Barriere (Stock, Schnur oder Hindernis) zwischen sich und dem Ziel.</li><li>Die Barriere sollte hoch genug sein, um einen Lob zu erfordern.</li></ul><p><strong>Bohren:</strong></p><ul><li>Um das Ziel zu treffen, muss die Barriere überwunden werden.</li><li>Jeder Wurf, der die Barriere trifft, ist &quot;tot&quot;.</li><li>Entwickelt einen hohen Ablösepunkt</li></ul><p><strong>Warum das wichtig ist:</strong></p><ul><li>Bei Wettkämpfen ist es oft erforderlich, über Hindernisse hinweg zu schießen.</li><li>Verleiht Ihnen mehr Vielseitigkeit beim Fotografieren</li></ul><h3 id="hindernisparcours" tabindex="-1">Hindernisparcours <a class="header-anchor" href="#hindernisparcours" aria-label="Permalink to &quot;Hindernisparcours&quot;">​</a></h3><p><strong>Zweck:</strong> Entwicklung von Aufnahmen aus verschiedenen Blickwinkeln</p><p><strong>Aufstellen:</strong></p><ul><li>Platziere die Zielkugel in der Mitte</li><li>Füge Hindernisse (andere Boules, Markierungen) darum herum hinzu.</li></ul><p><strong>Bohren:</strong></p><ul><li>Schieße aus verschiedenen Positionen rund um den Kreis.</li><li>Man muss den passenden Winkel finden.</li><li>Entwickelt das Lesen von Schusslinien</li></ul><h2 id="mentale-trainingsubungen" tabindex="-1">Mentale Trainingsübungen <a class="header-anchor" href="#mentale-trainingsubungen" aria-label="Permalink to &quot;Mentale Trainingsübungen&quot;">​</a></h2><h3 id="routinewiederholung" tabindex="-1">Routinewiederholung <a class="header-anchor" href="#routinewiederholung" aria-label="Permalink to &quot;Routinewiederholung&quot;">​</a></h3><p><strong>Zweck:</strong> Automatisieren Sie Ihre Vorbereitungsroutine.</p><p><strong>Bohren:</strong></p><ul><li>Übe deine gesamte Routine ohne zu werfen.</li><li>Gehen Sie jeden Schritt bewusst durch.</li><li>Führe 10-20 Wiederholungen durch.</li><li>Füge dann den Wurf hinzu.</li></ul><p><strong>Fokus:</strong></p><ul><li>Konstantes Timing</li><li>Klarer Übergang vom Denken zur Ausführung</li><li>Immer die gleiche Routine</li></ul><h3 id="druckpunkte" tabindex="-1">Druckpunkte <a class="header-anchor" href="#druckpunkte" aria-label="Permalink to &quot;Druckpunkte&quot;">​</a></h3><p><strong>Zweck:</strong> Üben Sie das Auftreten unter Druck</p><p><strong>Aufstellen:</strong></p><ul><li>Erstellen Sie ein „Must-Machen“-Szenario</li><li>Konsequenzen für das Versäumnis festlegen</li></ul><p><strong>Beispiele:</strong></p><ul><li>„Schaffe 3 in Folge oder fange von vorne an.“</li><li>&quot;Verpasse den Wurf und mach 10 Liegestütze.&quot;</li><li>&quot;Kündige dein Ziel an, bevor du wirfst.&quot;</li></ul><p><strong>Schlüssel:</strong></p><ul><li>Der Druck sollte sich real anfühlen.</li><li>Üben Sie Ihre mentale Reaktion auf Druck</li><li>Setze deine Routine genau wie im Wettkampf ein.</li></ul><h3 id="genesungspraxis" tabindex="-1">Genesungspraxis <a class="header-anchor" href="#genesungspraxis" aria-label="Permalink to &quot;Genesungspraxis&quot;">​</a></h3><p><strong>Zweck:</strong> Die Gewohnheit entwickeln, mental schnell wieder in einen Normalzustand zu versetzen.</p><p><strong>Bohren:</strong></p><ul><li>absichtlich einen schlechten Boule werfen</li><li>Wenden Sie sofort SOAS an (Stoppen, Beobachten, Akzeptieren, Ausrutschen).</li><li>Wirf die nächste Boule-Kugel mit vollem Einsatz.</li></ul><p><strong>Fokus:</strong></p><ul><li>Grübele nicht über den Fehler nach.</li><li>Vor dem nächsten Wurf vollständig zurücksetzen.</li><li>Achten Sie auf eine positive Körpersprache.</li></ul><h2 id="spielsimulationsubungen" tabindex="-1">Spielsimulationsübungen <a class="header-anchor" href="#spielsimulationsubungen" aria-label="Permalink to &quot;Spielsimulationsübungen&quot;">​</a></h2><h3 id="millieus-freude" tabindex="-1">Millieus Freude <a class="header-anchor" href="#millieus-freude" aria-label="Permalink to &quot;Millieus Freude&quot;">​</a></h3><p><strong>Zweck:</strong> Rhythmusblockaden durchbrechen, Vielseitigkeit aufbauen</p><p><strong>Bohren:</strong></p><ul><li>Wechsle bei jedem Wurf zwischen Zeigen und Werfen ab.</li><li>Keine zwei aufeinanderfolgenden Würfe der gleichen Art</li><li>Entwickelt die Fähigkeit, zwischen verschiedenen Modi zu wechseln</li></ul><h3 id="szenario-spiel" tabindex="-1">Szenario-Spiel <a class="header-anchor" href="#szenario-spiel" aria-label="Permalink to &quot;Szenario-Spiel&quot;">​</a></h3><p><strong>Zweck:</strong> Übung taktischer Entscheidungsfindung</p><p><strong>Aufstellen:</strong></p><ul><li>Realistische Spielsituationen schaffen</li><li>Punkte und Boule-Zählungen zuweisen</li></ul><p><strong>Beispiele:</strong></p><ul><li>&quot;Du liegst 10:8 hinten, dein Gegner hat 2 Punkte, du hast 2 Boules.&quot;</li><li>„Unentschieden 6:6, Sie haben die letzte Kugel, sie haben 1 Punkt.“</li></ul><p><strong>Bohren:</strong></p><ul><li>Entscheide, was du tun willst.</li><li>Mit vollem Engagement ausführen</li><li>Überprüfen Sie die Entscheidung anschließend.</li></ul><h3 id="matchplay-mit-regeln" tabindex="-1">Matchplay mit Regeln <a class="header-anchor" href="#matchplay-mit-regeln" aria-label="Permalink to &quot;Matchplay mit Regeln&quot;">​</a></h3><p><strong>Zweck:</strong> Wettbewerbssimulation</p><p><strong>Varianten:</strong></p><ul><li>Spiel bis 13 (vollständiges Spiel)</li><li>Spielt bis 7 (kürzer, mehr Spiele)</li><li>„Druckpunkte“ – bestimmte Ziele sind doppelt so viel wert</li><li>„Plötzlicher Tod“ – wer als Erster eine Runde verliert, verliert das Spiel.</li></ul><h2 id="protokollierung-ihrer-ubungen" tabindex="-1">Protokollierung Ihrer Übungen <a class="header-anchor" href="#protokollierung-ihrer-ubungen" aria-label="Permalink to &quot;Protokollierung Ihrer Übungen&quot;">​</a></h2><p>Führen Sie für jede Übung ein Protokoll:</p><table tabindex="0"><thead><tr><th>Datum</th><th>Bohren</th><th>Ergebnis</th><th>Anmerkungen</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Verlauf im Zeitverlauf:</strong></p><ul><li>Machst du Fortschritte?</li><li>Welche Übungen helfen am meisten?</li><li>Wo haben Sie Schwierigkeiten?</li></ul><h2 id="aufbau-einer-ubungseinheit" tabindex="-1">Aufbau einer Übungseinheit <a class="header-anchor" href="#aufbau-einer-ubungseinheit" aria-label="Permalink to &quot;Aufbau einer Übungseinheit&quot;">​</a></h2><h3 id="aufwarmen-10-min" tabindex="-1">Aufwärmen (10 Min.) <a class="header-anchor" href="#aufwarmen-10-min" aria-label="Permalink to &quot;Aufwärmen (10 Min.)&quot;">​</a></h3><ul><li>Einfache Würfe zum Aufwärmen</li><li>Kein Druck, einfach fühlen</li></ul><h3 id="technischer-schwerpunkt-20-30-min" tabindex="-1">Technischer Schwerpunkt (20-30 Min.) <a class="header-anchor" href="#technischer-schwerpunkt-20-30-min" aria-label="Permalink to &quot;Technischer Schwerpunkt (20-30 Min.)&quot;">​</a></h3><ul><li>Ein oder zwei Übungen zur Förderung spezifischer Fähigkeiten</li><li>Blockiertes Üben neuer Fähigkeiten</li><li>Zufälliges Üben für etablierte Fertigkeiten</li></ul><h3 id="druck-spielsimulation-20-30-min" tabindex="-1">Druck-/Spielsimulation (20-30 Min.) <a class="header-anchor" href="#druck-spielsimulation-20-30-min" aria-label="Permalink to &quot;Druck-/Spielsimulation (20-30 Min.)&quot;">​</a></h3><ul><li>Folgen hinzufügen</li><li>Realistische Szenarien erstellen</li><li>Mentale Fähigkeiten üben</li></ul><h3 id="abkuhlphase-10-min" tabindex="-1">Abkühlphase (10 Min.) <a class="header-anchor" href="#abkuhlphase-10-min" aria-label="Permalink to &quot;Abkühlphase (10 Min.)&quot;">​</a></h3><ul><li>Einfache Würfe</li><li>Reflektieren Sie die Sitzung</li><li>Notieren Sie sich, woran Sie als Nächstes arbeiten müssen.</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Bohrmaschinen sind Werkzeuge. Wählen Sie das richtige Werkzeug für Ihr Bauvorhaben.</p></blockquote><p>Werfen Sie nicht einfach nur Boule-Kugeln. Trainieren Sie zielgerichtet.</p>',69)),t(f)])}]]);export{g as __pageData,d as default};
